"mt__pMF-Xb0TE":{"intro":"Let's practice staying safe in an earthquake! 🛡️","items":[{"t":"order","q":"Put the earthquake safety steps in order.","steps":["Drop to your hands and knees","Cover your head under a sturdy table","Hold on until the shaking stops"]},{"t":"pick","q":"During an earthquake, what should you move away from?","opts":["Windows","Your table","The floor"],"why":"Glass can break and fall."},{"t":"tf","q":"During an earthquake, you should run outside right away.","a":false,"why":"Drop, cover and hold on where you are."},{"t":"pick","q":"After the shaking stops, who should you tell?","opts":["A trusted adult","Nobody","Your toy"],"why":"Grown-ups will help keep you safe."},{"t":"do","q":"Mission: with a grown-up, practice Drop, Cover and Hold On under a sturdy table at home."}]},
"mt_adpdEaKEBC":{"intro":"Earth changes — some changes are quick and some are super slow! ⚡🐢","items":[{"t":"sort","q":"Quick change or slow change?","bins":["Quick ⚡","Slow 🐢"],"items":[["volcano erupting 🌋",0],["earthquake",0],["water wearing away rock",1],["wind smoothing a rock",1]],"why":"Eruptions and quakes are fast; wearing away takes ages."},{"t":"pick","q":"A river slowly makes a rock smooth. Is this quick or slow?","opts":["Slow","Quick"],"why":"It takes a very long time."},{"t":"tf","q":"An earthquake can change the land in just a few seconds.","a":true,"why":"Earthquakes happen suddenly."},{"t":"pick","q":"What slowly wears away rock?","opts":["Wind and water","Sunglasses","Snacks"],"why":"Wind and water rub rock away a tiny bit at a time."},{"t":"pick","q":"Which changes the land quickly?","opts":["A volcano erupting","Rain over many years","A small stream"],"why":"Lava can cover land in hours."}]},
"mt_BLQ2_OXPod":{"intro":"Volcanoes are some of the most powerful things on Earth! 🌋💥","items":[{"t":"tf","q":"A volcanic eruption can change how the land looks.","a":true,"why":"Lava and ash can build new land and cover old land."},{"t":"pick","q":"Which of these can come out of an erupting volcano?","opts":["Lava, ash and gas","Ice cream","Rainbows"],"why":"Eruptions blast out hot rock, ash and gases."},{"t":"pick","q":"Hawaii's islands were made by…","opts":["volcanoes","beavers","glaciers"],"why":"Lava piled up from the ocean floor to make islands."},{"t":"sort","q":"Can an eruption do this?","bins":["Yes","No"],"items":[["make a new mountain",0],["cover land with ash",0],["make new land",0],["plant a garden",1]],"why":"Eruptions build and bury land."},{"t":"pick","q":"Why do people stay far away from erupting volcanoes?","opts":["Lava and ash are dangerous","Volcanoes are cold","They are too quiet"],"why":"Eruptions are very powerful and hot."}]},
"mt_S9SKah-yi_":{"intro":"What is a volcano? Let's find out! 🌋","items":[{"t":"pick","q":"A volcano is…","opts":["an opening where hot melted rock comes out","a very tall tree","a deep lake"],"why":"Melted rock escapes from inside Earth."},{"t":"pick","q":"Hot melted rock that comes out of a volcano is called…","opts":["lava","sand","snow"],"why":"Lava is melted rock on the surface."},{"t":"tf","q":"Lava is very, very hot.","a":true,"why":"Lava can be over 2,000°F!"},{"t":"pick","q":"What shape are many volcanoes?","opts":["Like a mountain or cone","Like a square","Like a flat puddle"],"why":"Many volcanoes are cone-shaped mountains."},{"t":"pick","q":"Where does the melted rock come from?","opts":["Deep inside the Earth","The clouds","The ocean waves"],"why":"It's very hot deep underground."}]},
"mt_e29VrLfmYt":{"intro":"Rumble rumble! What is an earthquake? 🌍","items":[{"t":"pick","q":"An earthquake is…","opts":["a sudden shaking of the ground","a big rainstorm","a strong wind"],"why":"The ground shakes suddenly."},{"t":"tf","q":"Some earthquakes are so weak people don't even feel them.","a":true,"why":"Earthquakes can be strong or weak."},{"t":"pick","q":"Which happens in a strong earthquake?","opts":["Things fall off shelves","It snows","The Sun sets"],"why":"Strong shaking makes things fall."},{"t":"sort","q":"Weak or strong earthquake?","bins":["Weak","Strong"],"items":[["only a cup rattles a little",0],["buildings are damaged",1],["nobody notices",0],["roads crack",1]],"why":"Stronger earthquakes cause more damage."},{"t":"pick","q":"Where does the shaking come from?","opts":["Rocks moving under the ground","The sky","Trucks only"],"why":"Earthquakes start underground."}]},
"mt_dSeFrAWE4v":{"intro":"Is the volcano awake, asleep, or done? 🌋😴","items":[{"t":"match","q":"Match each word to its meaning.","pairs":[["active","could erupt any time"],["dormant","sleeping but could wake up"],["extinct","will not erupt again"]]},{"t":"pick","q":"Kīlauea in Hawaii erupts often. It is…","opts":["active","extinct","dormant"],"why":"It has erupted many times recently."},{"t":"pick","q":"A volcano that hasn't erupted in thousands of years but still has magma below is…","opts":["dormant","extinct","active"],"why":"It's sleeping, not dead."},{"t":"tf","q":"An extinct volcano is expected to erupt again soon.","a":false,"why":"Extinct volcanoes are not expected to erupt again."},{"t":"sort","q":"Active or extinct?","bins":["Active","Extinct"],"items":[["erupted last year",0],["no magma supply left",1],["steam and gas coming out now",0],["worn down over millions of years",1]],"why":"Active volcanoes show recent activity."}]},
