"mt_bhwf_rDXQL":{"intro":"Volcanoes and earthquakes have favorite places! 🔥🗺️","items":[{"t":"pick","q":"The Ring of Fire circles which ocean?","opts":["Pacific","Atlantic","Arctic"],"why":"It runs around the edges of the Pacific."},{"t":"tf","q":"Volcanoes and earthquakes happen randomly all over Earth.","a":false,"why":"Most happen along plate edges, like the Ring of Fire."},{"t":"sort","q":"Is it on the Ring of Fire?","bins":["Ring of Fire","Not on it"],"items":[["Japan",0],["Alaska",0],["Chile",0],["Kansas",1],["England",1]],"why":"Pacific-edge places are in the Ring of Fire."},{"t":"pick","q":"Why are there so many earthquakes there?","opts":["Edges of Earth's plates meet there","It's very hot weather","There are many cities"],"why":"Plates push and slide along these edges."},{"t":"pick","q":"Which US state is on the Ring of Fire?","opts":["California","Florida","Ohio"],"why":"California sits along the Pacific edge."}]},
